"""Actual Gemma Q8 row width/vocabulary edges; independent wire/math anchors."""
from pathlib import Path
import math
import struct
ROOT=Path(__file__).parent
f32=lambda x:struct.unpack('<f',struct.pack('<f',x))[0]
E,V=1152,262144
RB=E//32*34
CODES=[((j*7+3)%31)-15 for j in range(32)]
CODES[0], CODES[31] = -128, 127
assert len(set(CODES))==32 and min(CODES)==-128 and max(CODES)==127
for scale in (.25,-.5):
    wire=struct.pack('<e',scale)+bytes(c&255 for c in CODES)
    decoded=struct.unpack('<32b',wire[2:])
    assert list(decoded)==CODES and len(wire)==34
    assert [struct.unpack('<e',wire[:2])[0]*c for c in decoded]==[scale*c for c in CODES]
text=['// Copyright 2026 AMD ROCm Software\n// SPDX-License-Identifier: MIT\n// Generated by q8_0_fixtures.py; independent signed byte/scaling oracle.\n']
text.append('template.decl @llm.token_embedding_q8_0_f32.row(%hidden:index,%row_bytes:index,%token:i32,%outorigin:offset,%scale:f32,%weight:buffer,%out:buffer)\n')
text.append('kernel.def @q8_0_test.gather() {\n  %one = index.constant 1 : index\n  %threads = index.constant 256 : index\n  kernel.launch.config workgroups(%one,%one,%one) workgroup_size(%threads,%one,%one) : index\n} launch(%token:i32,%scale:f32,%weight:buffer,%out:buffer) {\n  %width = index.constant 1152 : index\n  %rowbytes = index.constant 1224 : index\n  %origin = index.constant 16 : offset\n  template.apply<@llm.token_embedding_q8_0_f32.row>(%width,%rowbytes,%token,%origin,%scale,%weight,%out) : (index,index,i32,offset,f32,buffer,buffer)\n  kernel.return\n}\n')
text.append('func.def @q8_0_test.init(%weight:buffer) {\n  %zero = index.constant 0 : index\n  %one = index.constant 1 : index\n  %nb = index.constant 36 : index\n  %three = index.constant 3 : index\n  %stride = index.constant 34 : offset\n')
for row,token in enumerate((0,V-1)):
    text.append(f'  %row{row} = index.constant {token*RB} : offset\n  scf.for %b = [%zero to %nb step %one] {{\n    %bo = index.scale %b, %stride : index, offset -> offset\n    %base = index.add %row{row}, %bo : offset\n    %bytes = buffer.view %weight[%base] : buffer -> view<34xi8>\n')
    for j,c in enumerate(CODES):text.append(f'    %c{j} = scalar.constant {c} : i8\n    view.store %c{j}, %bytes[{j+2}] : i8, view<34xi8>\n')
    text.append(f'    %bm = index.rem %b, %three : index\n    %bp = index.add %bm, %one : index\n    %bi = index.cast %bp : index to i32\n    %bf = scalar.uitofp %bi : i32 to f32\n    %unit = scalar.constant {0.25 if row==0 else -0.5} : f32\n    %df = scalar.mulf %bf, %unit : f32\n    %dh = scalar.fptrunc %df : f32 to f16\n    %d = buffer.view %weight[%base] : buffer -> view<1xf16>\n    view.store %dh, %d[0] : f16, view<1xf16>\n  }}\n')
text.append('  func.return\n}\n')
# Token selection is an explicit test argument, not read back from encoded table.
text.append('func.def @q8_0_test.expected(%token:i32,%scale:f32,%weight:buffer,%out:buffer) {\n  %zero = index.constant 0 : index\n  %one = index.constant 1 : index\n  %nb = index.constant 36 : index\n  %three = index.constant 3 : index\n  %n32 = index.constant 32 : index\n  %origin = index.constant 16 : offset\n  %outview = buffer.view %out[%origin] : buffer -> view<1152xf32>\n  %first_id = scalar.constant 0 : i32\n  %first = scalar.cmpi eq, %token, %first_id : i32\n  %positive = scalar.constant 0.25 : f32\n  %negative = scalar.constant -0.5 : f32\n  %unit = scf.select %first, %positive, %negative : f32\n  scf.for %b = [%zero to %nb step %one] {\n    %bm = index.rem %b, %three : index\n    %bp = index.add %bm, %one : index\n    %bi = index.cast %bp : index to i32\n    %bf = scalar.uitofp %bi : i32 to f32\n    %d = scalar.mulf %bf, %unit : f32\n    %base = index.mul %b, %n32 : index\n')
for j,c in enumerate(CODES):text.append(f'    %j{j} = index.constant {j} : index\n    %at{j} = index.add %base, %j{j} : index\n    %logical{j} = scalar.constant {c}.0 : f32\n    %decoded{j} = scalar.mulf %logical{j}, %d : f32\n    %value{j} = scalar.mulf %decoded{j}, %scale : f32\n    view.store %value{j}, %outview[%at{j}] : f32, view<1152xf32>\n')
text.append('  }\n  func.return\n}\n')
for token in (0,V-1):
    for number,scale in enumerate((0.,1.,f32(math.sqrt(E)),-.5)):
        case=f'q8_0_token{token}_scale{number}'
        text.append(f'command.program.def @{case}.actual() launch(%weight:buffer,%out:buffer) {{\n  %token = scalar.constant {token} : i32\n  %scale = scalar.constant {scale!r} : f32\n  kernel.launch @q8_0_test.gather[](%token,%scale,%weight,%out) : [](i32,f32,buffer,buffer)\n  command.return\n}}\nfunc.def @{case}.expected(%weight:buffer,%out:buffer) {{\n  %token = scalar.constant {token} : i32\n  %scale = scalar.constant {scale!r} : f32\n  func.call @q8_0_test.expected(%token,%scale,%weight,%out) : (i32,f32,buffer,buffer) -> ()\n  func.return\n}}\n')
        text.append(f'check.scenario @q8_0_token{token}_scale{number} {{\n  check.trial[1](%trial:index,%entropy:check.entropy) {{\n    %owner = check.generate.fill value(0) : tensor<{RB*V+512}xi8>\n    %weight = check.tensor.view %owner offset(256) : tensor<{RB*V+512}xi8> -> tensor<{RB*V}xi8>\n    check.generate<@q8_0_test.init>(%weight) : (tensor<{RB*V}xi8>) -> ()\n    %out = check.generate.fill value(-777.0) : tensor<1160xf32>\n    check.compare<@{case}.actual,@{case}.expected>(%weight,%out) : (tensor<{RB*V}xi8>,tensor<1160xf32>) -> () {{\n      check.expect.bitwise actual(%owner) expected(%owner) : tensor<{RB*V+512}xi8>\n      check.expect.bitwise actual(%out) expected(%out) : tensor<1160xf32>\n    }}\n  }}\n  check.return\n}}\n')
(ROOT/'q8_0_checks.loom').write_text(''.join(text))
